CREATE  TABLE ATTIVITA(ID NUMERIC(8, 0) NOT NULL, FKIDPRATICHE NUMERIC(8, 0) NULL, IDATTIVITA VARCHAR(20) NULL, DATAATTIVITA DATETIME NULL, NUMPROTGEN VARCHAR(50) NULL, DATAPROTGEN DATETIME NULL, TIPOATTIVITA VARCHAR(150) NULL, DATASISTEMA DATETIME NULL, IDPROCEDIMENTO VARCHAR(30) NULL) ENGINE=INNODB DEFAULT CHARSET=UTF8;
CREATE  TABLE CONFIGURAZIONE(IDNODO NUMERIC(8, 0) NOT NULL, IDENTE VARCHAR(10) NULL, IDSPORTELLO VARCHAR(10) NULL, ENTE VARCHAR(50) NULL, SPORTELLO VARCHAR(100) NULL, WSURL VARCHAR(150) NULL, USERID VARCHAR(30) NULL, PASSWORD VARCHAR(30) NULL, IDDIREZIONE VARCHAR(10) NULL, DIREZIONE VARCHAR(50) NULL) ENGINE=INNODB DEFAULT CHARSET=UTF8;
CREATE  TABLE ID_TABLE(ID VARCHAR(30) NOT NULL, NEXT_ID NUMERIC(9, 0) NOT NULL) ENGINE=INNODB DEFAULT CHARSET=UTF8;
CREATE  TABLE MESSAGGIATTIVITA(ID NUMERIC(8, 0) NOT NULL, FKIDRICHIESTA NUMERIC(8, 0) NULL, FKIDRISPOSTA NUMERIC(8, 0) NULL) ENGINE=INNODB DEFAULT CHARSET=UTF8;
CREATE  TABLE MESSAGGIPRATICHE(ID NUMERIC(8, 0) NOT NULL, FKIDRICHIESTA NUMERIC(8, 0) NULL, FKIDRISPOSTA NUMERIC(8, 0) NULL) ENGINE=INNODB DEFAULT CHARSET=UTF8;
CREATE  TABLE PRATICHE(ID NUMERIC(8, 0) NOT NULL, IDENTE VARCHAR(10) NULL, IDSPORTELLO VARCHAR(10) NULL, IDPRATICA VARCHAR(30) NULL, NUMPRATICA VARCHAR(50) NULL, DATAPRATICA DATETIME NULL, NUMPROTGEN VARCHAR(50) NULL, DATAPROTGEN DATETIME NULL) ENGINE=INNODB DEFAULT CHARSET=UTF8;
CREATE  TABLE SICUREZZA(ID NUMERIC(8, 0) NOT NULL, TOKEN VARCHAR(32) NOT NULL, SCADENZA DATETIME NULL, FKIDNODO NUMERIC(8, 0) NOT NULL) ENGINE=INNODB DEFAULT CHARSET=UTF8;
CREATE TABLE VERSIONE 
(
  VERSIONE VARCHAR(15) 
) ENGINE=InnoDB DEFAULT CHARSET=utf8;
